// Loads the compiled case (generated by scripts/build-case.mjs) and indexes it.
// Server-only: imported by the Worker and by Node test scripts, never by the client.

import data from './generated/case.js';

export const caseData = data;
export const solution = data.solution;

const characters = new Map();
const facts = new Map();
const clues = new Map();
const cluePlacements = new Map();

for (const ch of data.characters ?? []) {
  characters.set(ch.id, ch);
  for (const f of ch.facts ?? []) facts.set(f.id, { ...f, character: ch.id });
}
for (const clue of data.clues ?? []) clues.set(clue.id, clue);
for (const room of data.rooms ?? []) {
  for (const h of room.hotspots ?? []) {
    if (h.type === 'clue') cluePlacements.set(h.clue, { room: room.id, hotspot: h.id });
  }
}

export const getCharacter = (id) => characters.get(id) ?? null;
export const getClue = (id) => clues.get(id) ?? null;
export const getCluePlacement = (id) => cluePlacements.get(id) ?? null;
export const allFacts = () => [...facts.values()];

export const toDiscoveredSet = (value) =>
  value instanceof Set ? value : new Set(value ?? []);

export function factUnlocked(fact, discovered) {
  if (fact.unlock === 'always') return true;
  const requires = fact.unlock?.requires ?? [];
  return requires.every((r) => discovered.has(r));
}
